//! Compile checked, logical text projections into direct parser/printer code.
//! Scanning and symbol resolution remain shared runtime primitives.
mod emit;
mod schema;

use std::fmt::Write;

use crate::Error;
use crate::model::Definitions;
use crate::packing::alternate;

pub(crate) fn generate(defs: &Definitions, source: &str) -> Result<(String, String), Error> {
    let mut parser = String::from(
        "// @generated by veloc-opgen; edit the .ops definitions.\nimpl OperandParser<'_> {\nfn parse(&mut self, opcode: crate::Opcode, flags: crate::MemFlags, input: &mut Cursor<'_>) -> core::result::Result<crate::InstDraft, ParseError> {\nmatch opcode {\n",
    );
    let mut printer = String::from(
        "// @generated by veloc-opgen; edit the .ops definitions.\nimpl InstPrinter<'_> {\nfn fmt_instruction_data(&self, f: &mut dyn core::fmt::Write, data: &crate::InstructionView<'_>, ty: Option<crate::Type>) -> core::fmt::Result {\nmatch data.opcode() {\n",
    );
    for op in &defs.ops {
        let format = defs
            .storage
            .formats
            .iter()
            .find(|f| f.name == op.format)
            .expect("checked format");
        let schema = schema::compile(op, &defs.storage.records, source, &defs.types)?;
        let mut alternatives = defs
            .storage
            .alternatives
            .iter()
            .filter(|alt| alt.formats.contains(&op.format));
        let alternative = alternatives.next();
        // Dispatch must be unambiguous without inspecting opcode-specific names.
        // More than one alternate needs a declared discriminator first.
        if alternatives.next().is_some() {
            return Err(Error::at(
                source,
                op.offset,
                "multiple text alternatives need an explicit discriminator",
            ));
        }
        writeln!(parser, "crate::Opcode::{} => {{", op.name).unwrap();
        writeln!(printer, "crate::Opcode::{} => match data {{", op.name).unwrap();
        if let Some(alt) = alternative {
            let (alt_op, alt_format) = alternate(op, alt, source)?;
            let alt_schema = schema::compile(&alt_op, &defs.storage.records, source, &defs.types)?;
            if !schema.named.is_empty()
                || alt_schema.named.is_empty()
                || !alt_schema
                    .named
                    .iter()
                    .any(|n| matches!(n.mode, schema::Mode::Required))
            {
                return Err(Error::at(
                    source,
                    alt.text.offset,
                    "text alternative requires distinct, required named fields",
                ));
            }
            parser.push_str("if input.has_named() {\n");
            parser.push_str(&emit::parse(
                &alt_op,
                &alt_format,
                &alt_schema,
                &defs.storage.records,
                format.arity,
            ));
            parser.push_str("} else {\n");
            printer.push_str(&emit::print(
                op,
                &alt_op,
                &alt_format,
                &alt_schema,
                format.arity,
            ));
        }
        parser.push_str(&emit::parse(
            op,
            format,
            &schema,
            &defs.storage.records,
            None,
        ));
        if alternative.is_some() {
            parser.push_str("}\n");
        }
        parser.push_str("},\n");
        printer.push_str(&emit::print(op, op, format, &schema, None));
        printer.push_str("_ => Err(core::fmt::Error),\n},\n");
    }
    parser.push_str("}\n}\n}\n");
    printer.push_str("}\n}\n}\n");
    Ok((parser, printer))
}
